// Worker entry for Cloudflare: the OpenNext app plus the consumer of the background-job Queue.
// See src/lib/jobs.ts for why jobs go through a Queue.
// Generated by `opennextjs-cloudflare build`; this file is bundled by wrangler and left out of tsc (tsconfig.json).
import app from "../.open-next/worker.js";

type Env = {
  WORKER_SELF_REFERENCE: { fetch(input: string, init?: RequestInit): Promise<Response> };
  AUTH_SECRET: string;
};
type Message = { body: unknown; ack(): void };

const worker = {
  fetch: app.fetch,

  /** One job per message (max_batch_size 1). A failed job is recorded on its row, so it is not retried. */
  async queue(batch: { messages: Message[] }, env: Env) {
    for (const message of batch.messages) {
      const res = await env.WORKER_SELF_REFERENCE.fetch("https://apslop.internal/api/internal/jobs", {
        method: "POST",
        headers: { "content-type": "application/json", "x-apslop-job-token": env.AUTH_SECRET },
        body: JSON.stringify(message.body),
      });
      if (!res.ok) console.error(`job failed: ${res.status} ${await res.text()}`);
      message.ack();
    }
  },
};

export default worker;
